namespace EquipmentApp.Models;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using EquipmentApp.Models;

namespace EquipmentApp.Services;

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a slow data source so the "Loading inventory..." message is visible.
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Hydraulic Press",      Location = "Building A",  LastInspected = new(2026, 3, 12) },
            new() { Id = 2, Name = "CNC Lathe",            Location = "Building B",  LastInspected = new(2026, 5, 20) },
            new() { Id = 3, Name = "Forklift #7",          Location = "Warehouse",   LastInspected = new(2026, 6, 1)  },
            new() { Id = 4, Name = "Conveyor Belt Motor",  Location = "Building A",  LastInspected = new(2025, 11, 8) },
            new() { Id = 5, Name = "Welding Robot Arm",    Location = "Building C",  LastInspected = new(2026, 1, 15) },
            new() { Id = 6, Name = "Air Compressor",       Location = "Utility Room", LastInspected = new(2026, 4, 22) },
            new() { Id = 7, Name = "Overhead Crane",       Location = "Building B",  LastInspected = new(2026, 2, 9)  },
            new() { Id = 8, Name = "Packaging Machine",    Location = "Warehouse",   LastInspected = new(2026, 6, 10) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@attribute [StreamRendering]

@using EquipmentApp.Models
@using EquipmentApp.Services
@implements IDisposable

@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistSubscription;

    protected override async Task OnInitializedAsync()
    {
        // If persisted state exists (circuit reconnect after prerender), use it
        // instead of calling the service again. This avoids the double-fetch.
        _persistSubscription = ApplicationState.RegisterOnPersisting(PersistData);

        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>("inventory", out var restored))
        {
            _items = restored;
        }
        else
        {
            _items = await EquipmentSvc.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson("inventory", _items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _persistSubscription.Dispose();
    }
}

